const payload = $json.body ?? $json;
const event = payload.event ?? payload.type ?? '';
const data = payload.data ?? payload.message ?? payload;
const sender = data.key?.remoteJid ?? data.sender ?? data.from ?? payload.sender ?? payload.from ?? '';
const pushName = data.pushName ?? data.senderName ?? payload.pushName ?? payload.senderName ?? '';
const textMessage = data.message?.conversation ?? data.message?.extendedTextMessage?.text ?? data.message?.imageMessage?.caption ?? data.message?.videoMessage?.caption ?? data.text ?? data.body ?? payload.text ?? payload.body ?? '';
const mediaUrl = data.message?.imageMessage?.url ?? data.message?.videoMessage?.url ?? data.mediaUrl ?? payload.mediaUrl ?? '';
const shouldIgnore = [
  !sender,
  String(sender).includes('@g.us'),
  String(sender).includes('status@broadcast'),
  Boolean(data.key?.fromMe),
  event && !['messages.upsert', 'message.upsert', 'messages.update', 'send.message'].includes(String(event)),
].some(Boolean);

if (shouldIgnore) {
  return [];
}

const tenantId = String($env.WHATSAPP_TENANT_ID || '').trim();
const eventId = String(data.key?.id ?? data.id ?? payload.messageId ?? '').trim();
if (!tenantId || !eventId || !$env.WHATSAPP_INGEST_TOKEN) throw new Error('Empresa, credencial e ID estável da mensagem são obrigatórios.');

const cleanPhone = String(sender).replace(/@s\.whatsapp\.net$/, '').replace(/\D/g, '');
const customerName = String(pushName || cleanPhone || 'Cliente WhatsApp').trim();
const sourceMessage = String(textMessage || '').trim();
const title = sourceMessage
  ? `WhatsApp - ${customerName} - ${sourceMessage.slice(0, 60)}`
  : `WhatsApp - ${customerName}`;

return [{
  json: {
    tenantId,
    eventId,
    title,
    type: 'orcamento',
    status: 'aguardando-orcamento',
    customerName,
    customerPhone: cleanPhone,
    sourceMessage,
    description: sourceMessage,
    requestedQuantity: 1,
    productionTimeHours: 0,
    referenceImageUrl: mediaUrl,
  },
}];
